    14	/** Orders by id, from the warehouse export. */
    15	export const ORDERS: Record<string, Order> = orders;
    16	
    17	/** Refund issued against an order. */
    18	export interface Refund {
    19	  orderId: string;
    20	  amount: number;
    21	}
    22	
    23	/** Refunds by id. */
    24	export const REFUNDS: Record<string, Refund> = {};
    25	
    26	/** Records a refund and returns its id. Throws if the order is unknown or not refundable. */
    27	export const createRefund = (orderId: string, amount: number): string => {
    28	  const order = ORDERS[orderId];
    29	  if (!order) throw new Error(`Order ${orderId} not found`);
    30	  if (!order.refundable) throw new Error(`Order ${orderId} is not refundable`);
    31	  const refundId = `R-${1001 + Object.keys(REFUNDS).length}`;
    32	  REFUNDS[refundId] = { orderId, amount };
    33	  return refundId;
    34	};
